def lcs_length(s, t):
    from collections import Counter

    dp = Counter()

    for i in range(len(s) + 1):
        for j in range(len(t) + 1):
            if i == 0 or j == 0:
                dp[i, j] = 0
            elif s[i - 1] == t[j - 1]:
                dp[i, j] = dp[i - 1, j - 1] + 1
            else:
                dp[i, j] = max(dp[i - 1, j], dp[i, j - 1])

    return dp[len(s), len(t)]

